#include <list>
#include <iostream>

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float life;
};

void update_particles(std::list<Particle>& particles, float dt) {
    for (auto it = particles.begin(); it != particles.end(); ) {
        it->x += it->vx * dt;
        it->y += it->vy * dt;
        it->life -= dt;
        if (it->life <= 0) {
            it = particles.erase(it);
        } else {
            ++it;
        }
    }
}

output:
#include <vector>
#include <iostream>

struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float life;
};

void update_particles(std::vector<Particle>& particles, float dt) {
    size_t write_idx = 0;
    for (size_t i = 0; i < particles.size(); ++i) {
        particles[i].x += particles[i].vx * dt;
        particles[i].y += particles[i].vy * dt;
        particles[i].life -= dt;
        if (particles[i].life > 0) {
            if (write_idx != i) {
                particles[write_idx] = particles[i];
            }
            write_idx++;
        }
    }
    particles.resize(write_idx);
}
---std::list stores elements in non-contiguous memory, causing frequent CPU cache misses during iteration. std::vector stores elements contiguously, maximizing cache spatial locality and enabling hardware prefetching. The erase-remove idiom (or manual swap-remove/overwrite) on a vector is significantly faster for batch updates.

