    char* text;
    DialogueNode** choices;
};

output:
#include <vector>
struct DialogueNode {
    std::string text;
    std::vector<int> next_node_indices;
};

std::vector<DialogueNode> conversation;
---Using indices into a central vector handles serialization/deserialization much easier than pointers and ensures the entire dialogue tree is loaded into a contiguous memory region.

input:
struct AStarNode {
    int x, y;
    AStarNode* parent;
};

// OpenList using linked nodes

output:
#include <vector>
struct Node { int x, y; int parent_index; };

std::vector<Node> all_nodes;
// Use indexes for parent references
---Pathfinding generates many nodes. Storing them in a vector (often with a separate 'generation' ID for reuse) prevents the massive allocation/deallocation churn of pointer nodes.

input:
struct OctNode {
    OctNode* kids[8];
};

// Pointer octree

output:
#include <vector>
struct OctNode { uint32_t child_mask; int first_child_idx; };

std::vector<OctNode> octree;
---Sparse Voxel Octrees (SVO) rely on being compact to fit in cache/GPU memory. Pointer-based nodes bloat the size (8 pointers = 64 bytes). Index-based nodes can be much smaller.

input:
struct Keyframe {
    float time;
    Keyframe* next;
};

// Linked list of frames

output:
#include <vector>
struct Keyframe {
    float time;
    // value
};

std::vector<Keyframe> track;
---Animation tracks must be sampled via binary search (or cached index) by time. Random access on a linked list is O(N), whereas a vector supports O(log N) search and O(1) access.

input:
struct Fragment {
    char data[128];
    Fragment* next;
};

// Packet reassembly list

output:
#include <vector>
struct Fragment {
    char data[128];
};

std::vector<Fragment> buffer;
---Network buffers benefit from linearity. Copying data out of a linked list of fragments is slow. A contiguous vector allows direct `memcpy` to the final destination buffer.

input:
#include <vector>

// Fixed 4x4 matrix
std::vector<float> matrix(16);

void identity() {
    for(int i=0; i<16; ++i) matrix[i] = (i%5==0 ? 1.0f : 0.0f);
}

output:
#include <array>

std::array<float, 16> matrix;

void identity() {
    for(int i=0; i<16; ++i) matrix[i] = (i%5==0 ? 1.0f : 0.0f);
}
---For small, fixed-size data like matrices, `std::vector` forces heap allocation and dynamic sizing overhead. `std::array` allocates on the stack, is completely zero-overhead, and allows the compiler to fully unroll loops.

input:
#include <vector>

std::vector<float> quat(4);

void set_quat(float x, float y, float z, float w) {
    quat[0]=x; quat[1]=y; quat[2]=z; quat[3]=w;
}

output:
#include <array>

std::array<float, 4> quat;

void set_quat(float x, float y, float z, float w) {
    quat[0]=x; quat[1]=y; quat[2]=z; quat[3]=w;
}
---Using `std::vector` for a 4-float quaternion is extremely wasteful (allocator latency, pointer indirection). `std::array` puts the data directly in the registers or stack, matching the performance of raw C arrays with C++ safety.

input:
#include <vector>

std::vector<float> kernel(9); // 3x3 convolution

void set_k() { /* fill */ }

output:
#include <array>

std::array<float, 9> kernel;

void set_k() { /* fill */ }
---Convolution kernels are usually constant size. `std::array` conveys this size to the compiler at compile-time, enabling aggressive loop unrolling and vectorization optimizations that `std::vector` (runtime size) precludes.

input:
#include <vector>
struct Color { unsigned char r,g,b; };

std::vector<unsigned char> pixel(3);

void set_red() { pixel[0] = 255; }

output:
#include <array>

std::array<unsigned char, 3> pixel;

void set_red() { pixel[0] = 255; }
---Allocating 3 bytes on the heap via `std::vector` is a massive performance antipattern. The allocator overhead alone is magnitudes larger than the data. `std::array` is the correct choice.

